import{_ as e,o,c as n,a as r}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const x=JSON.parse('{"title":"FinContext MCP — финансовый контекст для AI-ассистента","description":"Кейс FinContext MCP: self-hosted MCP-сервер, который сводит банки и учётную систему бизнеса. Развёртывание в Yandex Cloud клиента, токены в его Lockbox.","frontmatter":{"site":"pro","title":"FinContext MCP — финансовый контекст для AI-ассистента","description":"Кейс FinContext MCP: self-hosted MCP-сервер, который сводит банки и учётную систему бизнеса. Развёртывание в Yandex Cloud клиента, токены в его Lockbox.","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/work/fincontext"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"FinContext MCP — финансовый контекст для AI-ассистента"}],["meta",{"property":"og:description","content":"Кейс FinContext MCP: self-hosted MCP-сервер, который сводит банки и учётную систему бизнеса. Развёртывание в Yandex Cloud клиента, токены в его Lockbox."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/work/fincontext"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"FinContext MCP — финансовый контекст для AI-ассистента"}],["meta",{"name":"twitter:description","content":"Кейс FinContext MCP: self-hosted MCP-сервер, который сводит банки и учётную систему бизнеса. Развёртывание в Yandex Cloud клиента, токены в его Lockbox."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"work/fincontext.md","filePath":"work/fincontext.md"}'),a={name:"work/fincontext.md"};function i(l,t,c,s,p,d){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="fincontext-mcp-—-финансовыи-контекст-для-ai-ассистента" tabindex="-1">FinContext MCP — финансовый контекст для AI-ассистента <a class="header-anchor" href="#fincontext-mcp-—-финансовыи-контекст-для-ai-ассистента" aria-label="Permalink to &quot;FinContext MCP — финансовый контекст для AI-ассистента&quot;">​</a></h1><p><strong>Задача.</strong> У бизнеса деньги размазаны по счетам в разных банках и по учётной системе. На вопрос «сколько у нас реально свободных денег» отвечает бухгалтер через день, а не система.</p><p><strong>Ограничения.</strong> Токены банков нельзя отдавать разработчику. Облако — чужое. Ответ должен быть проверяемым, а не «модель посчитала».</p><h2 id="что-сделал" tabindex="-1">Что сделал <a class="header-anchor" href="#что-сделал" aria-label="Permalink to &quot;Что сделал&quot;">​</a></h2><p>MCP-сервер, который подключает ассистента сразу ко всем банкам и учёту и отвечает на живые вопросы:</p><ul><li>реальный остаток по всем счетам;</li><li>прошёл ли конкретный платёж;</li><li>прогноз кассового разрыва;</li><li>сверка выписки с учётом.</li></ul><p><strong>Модель доверия.</strong> Клиент разворачивает сервер у себя: Terraform в его Yandex Cloud, токены банков и учёта read-only лежат в его Lockbox. Код открыт для аудита, данные не покидают контур.</p><p><strong>Стек.</strong> Yandex Cloud Functions, API Gateway, YDB, Lockbox, Terraform. Базовые коннекторы — Точка и МойСклад. Pro-лицензия открывает движок сверки, прогноз, 1С и алерты.</p><h2 id="доказательство" tabindex="-1">Доказательство <a class="header-anchor" href="#доказательство" aria-label="Permalink to &quot;Доказательство&quot;">​</a></h2><ul><li>Репозиторий: <a href="https://github.com/alterfo/fincontext-mcp" target="_blank" rel="noreferrer">github.com/alterfo/fincontext-mcp</a></li><li>Деплой описан пошагово: Terraform-модуль, least-privilege сервисный аккаунт, инструкция для MCP-клиента.</li><li>Есть демо-инстанс на демо-данных, без чужих токенов.</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Новые коннекторы: банки и учётные системы, которые чаще спрашивают.</li><li>Импорт из 1С без ручного маппинга.</li><li>Метрика времени ответа на типовые вопросы: сейчас важнее корректность сверки.</li></ul>',12)])])}const h=e(a,[["render",i]]);export{x as __pageData,h as default};
